function UICultivateEquipSuitInfoDescNode:RefreshUI(coreEffectVo)
    self.SuitIcon.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(coreEffectVo.iconPath)

    local coreId = coreEffectVo.coreId
