    self.NameText.text = goodsVo.name
    ---@type EquipLabelVo
    --local equipLabelVo = cardConfMgr:GetEquipLabelVoByRefId(equipSuitVo.labelType)
    --self.SuitTypeName.text = equipLabelVo.name
    --self.SuitTypeBg.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(equipLabelVo.nameBg)

    KTool.GetComponent(self.DescText.gameObject, TextType).text = EquipUtils.GetEquipSuitDesc(coreEffectVo.refId)

    self:FixCellSize()
end

function UICultivateEquipSuitInfoDescNode:FixCellSize()
    local descTextTrans = self.DescText
    KTool.GetComponent(descTextTrans.gameObject, ContentSizeFitterType):SetLayoutVertical()
    ---@type UnityEngine.RectTransform
    local descTextRt = KTool.GetComponent(descTextTrans.gameObject, RectTransformType)
    local y = descTextRt.anchoredPosition.y * -1 + descTextRt.sizeDelta.y
    local rt = KTool.GetComponent(self.controller.transform.gameObject, RectTransformType)
    rt:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, y);
end

